local util = require 'XLua.util'
local support = require 'Frame.support'
local cs_coroutine = require 'XLua.cs_coroutine'
local KTool = CS.Engine.Lib.KTool
local CSGameUtils = CS.GameUtils
local MonoHelper = CS.Engine.Lib.MonoHelper
local ResourceModule = CS.Engine.Modules.ResourceModule
local RolesShowMgr = import('Game.Robot.RolesShowMgr')
local ChapterProcessor = CS.Playables.ChapterProcessor
local WaitForTimelineFinish = CS.WaitForTimelineFinish

---@class QTE2Mgr
local QTE2Mgr = Class('QTE2Mgr')

function QTE2Mgr:__init()
    --
end

function QTE2Mgr:__delete()
    --
end

function QTE2Mgr:Awake()
    
end

function QTE2Mgr:Start()
    
end

function QTE2Mgr:Initialize()

    local r = RolesShowMgr:GetInstance():GetRoleInstance("108")
    if not isNull(r) then
        r = r._modelGo
        printInfo(r.name)

    end
    self.model = r
    if not isNull(self.model) then
        self.initState = {}
        self.initState.parent = r.transform.parent
        self.initState.localPosition = r.transform.localPosition
        self.initState.localRotation = r.transform.localRotation
        self.initState.localScale = r.transform.localScale
        self.initState.active = r.activeInHierarchy
    end

    --KTool.SetActive(r, false)
    self.processor = self.controller.gameObject:GetComponentInChildren(typeof(ChapterProcessor))
    self.markers = self.processor:GetAllWaitTLFinishMarkers()
    self.light = CS.UnityEngine.GameObject.Find("Directional Light")
end

function QTE2Mgr:BindModel(director, model)
    local trackNameAni = "108008_home_ani"
    local trackNameAct = "108008_home_act"
    local parentName = "108008"
    local parentLoc = "108008_home_loc"
    local list = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    list:AddRange(director.playableAsset.outputs)
    for i = 1, list.Count do
        local pb = list[i - 1]
        if pb.streamName == trackNameAct or pb.streamName == trackNameAni then
            director:SetGenericBinding(pb.sourceObject, model)
        end
    end

    if not isNull(model) then
        local parent = director.transform:Find(parentName)
        if isNull(parent) then
            parent = director.transform:Find(parentLoc)
        end
        model.transform:SetParent(parent)
        model.transform.localRotation = Quaternion.Euler(0,0,0)
        KTool.ResetTransform(model.transform)
    end
    
end

function QTE2Mgr:BindLight(director, light)
    local trackName = "light_pos"
    local list = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    list:AddRange(director.playableAsset.outputs)
    for i = 1, list.Count do
        local pb = list[i - 1]
        if pb.streamName == trackName then
            director:SetGenericBinding(pb.sourceObject, light)
        end
    end
end

function QTE2Mgr:StartPlay()
    self.waitCo = cs_coroutine.start(function()

        printInfo("qte2 start")
        local director = nil
        local pre = nil
        if isNull(self.markers) then
            return
        end

        for i = 1, self.markers.Count do
            director = self.markers[i - 1].Director:Resolve(self.processor.DirectorControl)
            if not isNull(director) then
                KTool.SetActive(director.gameObject, true)

                self:BindModel(director, self.model)
                
                self:BindLight(director, self.light)

                if director.gameObject.name == "OP2_part02" then
                    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                    
                    --local pos = director.transform.localPosition
                    --pos.y = -100
                    --director.transform.localPosition = pos
                end

                if not isNull(pre) then
                    KTool.SetActive(pre, false)
                end

                pre = director
                director:Play()

                if not isNull(self.processor.OnSingleChapterStart) then
                    self.processor.OnSingleChapterStart(director)
                end

                coroutine.yield(WaitForTimelineFinish(director))

                if not isNull(self.processor.OnSingleChapterFinish) then
                    self.processor.OnSingleChapterFinish(director)
                end
                --if director.gameObject.name == "" then
                --    KTool.SetActive(self.model, false)
                --end
            end
        end

        if not isNull(self.processor.OnChapterFinish) then
            self.processor.OnChapterFinish()
        end

        if not isNull(self.model) then
            local r = self.model
            r.transform:SetParent(self.initState.parent)
            r.transform.localPosition = self.initState.localPosition
            r.transform.localRotation = self.initState.localRotation
            r.transform.localScale = self.initState.localScale
            KTool.SetActive(r, self.initState.active)
        end

        printInfo("qte2 end")
    end)
    
    return self.waitCo
end

function QTE2Mgr:OnDestroy()
    
    if not isNull(self.model) then
        local r = self.model
        r.transform:SetParent(self.initState.parent)
        r.transform.localPosition = self.initState.localPosition
        r.transform.localRotation = self.initState.localRotation
        r.transform.localScale = self.initState.localScale
        KTool.SetActive(r, self.initState.active)
    end
    
    if self.waitCo then
        cs_coroutine.stop(self.waitCo)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return QTE2Mgr